def blocks(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and (i,j) not in seen:
                st=[(i,j)]; comp=set()
                while st:
                    p=st.pop()
                    if p in seen: continue
                    seen.add(p); comp.add(p)
                    x,y=p
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(x+dx,y+dy)
                        if 0<=q[0]<h and 0<=q[1]<w and g[q[0]][q[1]]==2 and q not in seen:
                            st.append(q)
                out.append(sorted(comp))
    return out

