def transform6(g):
    h,w=len(g),len(g[0]); out=[row[:] for row in g]
    hrows=sorted({i for i in range(h) if g[i][0]==1 or g[i][w-1]==1})
    vcols=sorted({j for j in range(w) if g[0][j]==1 or g[h-1][j]==1})
    for comp in blocks(g):
        hit=False
        for r in hrows:
            rs=[p[0] for p in comp]
            if r0:=min(rs): pass
            if min(rs)<=r<=max(rs) or min(rs)-r==1 or r-max(rs)==1: hit=True
        for cc in vcols:
            cs_=[p[1] for p in comp]
            if min(cs_)<=cc<=max(cs_) or min(cs_)-cc==1 or cc-max(cs_)==1: hit=True
        if hit:
            for (i,j) in comp: out[i][j]=1
    for r in hrows:
        for j in range(w): out[r][j]=1
    for cc in vcols:
        for i in range(h): out[i][cc]=1
    return out
